insert into public.editorial_content_items (id, kind, payload, sort_order, created_at, updated_at, author_email) values
('student-council-about', 'research_resource', '{"editorialSurface": "page", "pagePath": "/students/council", "sectionId": "about", "entryType": "section", "title": "Про студентське самоврядування", "summary": "", "body": "<!-- APSVT_RICH_TEXT_V1 -->\n{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Студентське самоврядування — це гарантоване законодавством право здобувачів освіти самостійно або через своїх представників вирішувати питання, що належать до їхніх інтересів, брати участь в управлінні закладом вищої освіти, захищати свої права та інтереси, а також долучатися до формування освітнього, соціального, культурного й громадського середовища Академії.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Це не лише представництво інтересів студентства, а й простір для розвитку лідерських якостей, відповідальності, комунікації, командної роботи та громадянської активності.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Студентська рада — це виборний представницький орган студентського самоврядування, який забезпечує організацію його діяльності, представляє інтереси здобувачів освіти, координує роботу студентських представників та сприяє реалізації студентських ініціатив.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Студентська рада виступає важливою ланкою взаємодії між здобувачами освіти, адміністрацією Академії, факультетами та іншими структурними підрозділами.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Мета та основні завдання\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Метою діяльності студентського самоврядування є створення умов для активної участі здобувачів освіти в житті Академії, представництва їхніх інтересів, реалізації прав та можливостей, розвитку студентських ініціатив і формування відповідального, активного та згуртованого студентського середовища.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Основні завдання студентського самоврядування\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Захист прав та інтересів\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Представлення позиції здобувачів освіти, сприяння захисту їхніх прав та законних інтересів.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Участь в управлінні Академією\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Залучення представників студентства до обговорення та вирішення питань діяльності закладу в межах визначених повноважень.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Підтримка ініціатив\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Створення можливостей для реалізації ідей, пропозицій та студентських проєктів.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Розвиток студентської спільноти\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Сприяння взаємодії, співпраці та формуванню активного студентського середовища.\"}]},{\"type\":\"heading\",\"attrs\":{\"level\":3},\"content\":[{\"type\":\"text\",\"text\":\"Особистісний та професійний розвиток\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Розвиток лідерських, організаційних, комунікативних та управлінських компетентностей здобувачів освіти.\"}]}]}", "imageUrl": "", "imageAlt": "", "imageFit": "contain", "status": "published"}'::jsonb, 10, '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'editorial@apsvt.local'),
('student-council-pinchuk', 'research_resource', '{"editorialSurface": "page", "pagePath": "/students/council", "sectionId": "representation", "entryType": "section", "title": "Віола ПІНЧУК", "summary": "Голова студентської ради АПСВТ, здобувачка освіти юридичного факультету, спеціальність «Право» та «Публічне управління та адміністрування»", "body": "<!-- APSVT_RICH_TEXT_V1 -->\n{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"+380 (95) 029-63-55\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"tel:+380950296355\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"viola.pinchuk2513@gmail.com\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"mailto:viola.pinchuk2513@gmail.com\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Instagram\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"https://me-l.co/h8wt8z5u\"}}]}]}]}", "imageUrl": "/student-council/pinchuk.png", "imageAlt": "Віола ПІНЧУК", "imageFit": "contain", "status": "published"}'::jsonb, 20, '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'editorial@apsvt.local'),
