('student-council-kostiuchenko', 'research_resource', '{"editorialSurface": "page", "pagePath": "/students/council", "sectionId": "representation", "entryType": "section", "title": "Ольга КОСТЮЧЕНКО", "summary": "Голова студентського самоврядування юридичного факультету АПСВТ, здобувачка освіти юридичного факультету, спеціальність «Право»", "body": "<!-- APSVT_RICH_TEXT_V1 -->\n{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"+380 (96) 433-10-17\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"tel:+380964331017\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"8tvin.olya2007@gmail.com\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"mailto:8tvin.olya2007@gmail.com\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Instagram\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"https://me-l.co/6g1b7t4t\"}}]}]}]}", "imageUrl": "/student-council/kostiuchenko.png", "imageAlt": "Ольга КОСТЮЧЕНКО", "imageFit": "contain", "status": "published"}'::jsonb, 30, '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'editorial@apsvt.local'),
('student-council-mandziuk', 'research_resource', '{"editorialSurface": "page", "pagePath": "/students/council", "sectionId": "representation", "entryType": "section", "title": "Валентин МАНДЗЮК", "summary": "Голова студентського самоврядування факультету економіки, соціальних технологій та туризму АПСВТ, здобувач освіти факультету економіки, соціальних технологій та туризму, спеціальність «Професійна освіта»", "body": "<!-- APSVT_RICH_TEXT_V1 -->\n{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"+380 (66) 335-35-02\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"tel:+380663353502\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"valik07man@gmail.com\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"mailto:valik07man@gmail.com\"}}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Instagram\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"https://me-l.co/yhk3stxh\"}}]}]}]}", "imageUrl": "/student-council/mandziuk.png", "imageAlt": "Валентин МАНДЗЮК", "imageFit": "contain", "status": "published"}'::jsonb, 40, '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'editorial@apsvt.local')
